import numpy as np


class AntitheticPursuitMIDE:
    """Mixed-integer DE with Deb's rules and frequency-weighted, multiplicatively adapted
    constraint penalties. Before feasibility, the least-violating individuals are pursued with
    antithetic random-direction steps (per-individual adaptive step sizes), chronically violated
    constraints receive extra weight, and stalled populations are partly re-seeded. After
    feasibility: DE, 1/5-rule incumbent polishing, successful-step extrapolation, coordinate
    probes, blended line searches and stagnation restarts around the incumbent."""

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random
        dim = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vtypes = list(func.variable_types)
        ints = np.asarray(func.integer_indices, dtype=int)
        cont = np.asarray(func.continuous_indices, dtype=int)
        is_ord = np.array([str(v) == "ordinal" for v in vtypes], dtype=bool)

        nv = np.ones(dim, dtype=int)
        if len(ints):
            nv[ints] = np.maximum(1, np.round(ub[ints] - lb[ints]).astype(int))

        self.used = 0
        best = {"f": np.inf, "x": None}
        st = {"sum": None, "cnt": None, "freq": None, "lam": None}
        sig = {"loc": 0.01}
        ext = {"step": None, "fail": 0}

        def repair(x):
            x = np.asarray(x, dtype=float).copy()
            if len(cont):
                x[cont] = np.clip(x[cont], lb[cont], ub[cont])
            if len(ints):
                x[ints] = np.clip(np.round(x[ints]), 0, nv[ints] - 1)
            return x

        def rand_point():
            x = np.zeros(dim)
            if len(cont):
                x[cont] = rng.uniform(lb[cont], ub[cont])
            if len(ints):
                x[ints] = rng.randint(0, nv[ints])
            return x

        def weights():
            if st["freq"] is None:
                return None
            fr = st["freq"]
            # chronically violated constraints get an extra multiplier
            chronic = 1.0 + 1.0 * (fr > 0.35)
            return (1.0 + 4.0 * fr ** 2) * chronic * st["lam"]

        def key_of(f, g):
            gp = np.maximum(g, 0.0)
            if st["sum"] is None:
                v = float(np.sum(gp))
            else:
                scale = np.where(st["cnt"] > 0,
                                 st["sum"] / np.maximum(st["cnt"], 1), 1.0)
                scale = np.maximum(scale, 1e-12)
                term = gp / scale
                w = weights()
                if w is not None:
                    term = w * term
                v = float(np.sum(term))
            if not np.isfinite(f):
                return (1, v + 1.0)
            if v == 0.0:
                return (0, f)
            return (1, v)

        def evaluate(x):
            if self.used >= self.budget:
                return None
            x = repair(x)
            self.used += 1
            f, g = func(x)
            f = float(f)
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(),
                              nan=1e6, posinf=1e6, neginf=0.0)
            gp = np.maximum(g, 0.0)
            ind = (gp > 0).astype(float)
            if st["sum"] is None:
                st["sum"] = np.zeros(len(g))
                st["cnt"] = np.zeros(len(g))
                st["freq"] = ind.copy()
                st["lam"] = np.ones(len(g))
            else:
                st["freq"] = 0.97 * st["freq"] + 0.03 * ind
                st["lam"] = np.clip(st["lam"] * np.exp(0.05 * (st["freq"] - 0.15)),
                                    0.5, 8.0)
            st["sum"] += gp
            st["cnt"] += ind
            if not np.isfinite(f):
                f = np.inf
            k = key_of(f, g)
            if k[0] == 0 and f < best["f"]:
                best["f"] = f
                best["x"] = x.copy()
            return x, f, g

        def perturb(x, scale_factor=None):
            y = x.copy()
            s = rng.choice([0.02, 0.1, 0.3]) if scale_factor is None else scale_factor
            if len(cont):
                tmp = y[cont]
                mm = rng.rand(len(cont)) < 0.3
                tmp[mm] += rng.normal(0.0, s, mm.sum()) * (ub[cont][mm] - lb[cont][mm])
                y[cont] = tmp
            if len(ints):
                tmp = y[ints]
                mm = rng.rand(len(ints)) < min(1.0, 2.0 / len(ints))
                if mm.any():
                    tmp[mm] = rng.randint(0, nv[ints][mm])
                y[ints] = tmp
            return repair(y)

        def local_move(x):
            y = x.copy()
            s = sig["loc"]
            if len(cont):
                tmp = y[cont]
                mm = rng.rand(len(cont)) < max(1.0 / len(cont), 0.15)
                if not mm.any():
                    mm[rng.randint(len(cont))] = True
                tmp[mm] += rng.normal(0.0, s, mm.sum()) * (ub[cont][mm] - lb[cont][mm])
                y[cont] = tmp
            if len(ints):
                k = ints[rng.randint(len(ints))]
                if is_ord[k] and rng.rand() < 0.6:
                    y[k] = y[k] + (1 if rng.rand() < 0.5 else -1)
                else:
                    y[k] = rng.randint(0, nv[k])
            return repair(y)

        def coord_probe(x):
            y = x.copy()
            j = cont[rng.randint(len(cont))]
            step = sig["loc"] * 3.0 * (ub[j] - lb[j]) * rng.choice([-1.0, 1.0])
            y[j] = y[j] + step
            return repair(y)

        def extrapolate(x):
            y = x.copy()
            a = rng.uniform(0.5, 1.5)
            if len(cont):
                y[cont] = x[cont] + a * ext["step"][cont]
            return repair(y)

        def pursue(x, f, g, k, nevals, s):
            """Antithetic random-direction pursuit of the violation key.
            s is this individual's own step scale (normalised units); returns updated state."""
            cur, cf, cg, ck = x, f, g, k
            used_here = 0
            while used_here < nevals:
                if self.used >= self.budget or ck[0] == 0:
                    break
                d = np.zeros(dim)
                if len(cont):
                    mm = rng.rand(len(cont)) < 0.5
                    if not mm.any():
                        mm[rng.randint(len(cont))] = True
                    dc = rng.normal(0.0, 1.0, len(cont)) * mm
                    d[cont] = dc * (ub[cont] - lb[cont]) * s
                if len(ints) and rng.rand() < 0.3:
                    kk = ints[rng.randint(len(ints))]
                    if is_ord[kk] and rng.rand() < 0.5:
                        d[kk] = 1 if rng.rand() < 0.5 else -1
                    else:
                        d[kk] = (rng.randint(0, nv[kk]) - cur[kk])
                improved = False
                for sign in (1.0, -1.0):  # antithetic pair
                    if self.used >= self.budget or used_here >= nevals:
                        break
                    y = cur + sign * d
                    if sign < 0 and improved:
                        break
                    r = evaluate(y)
                    used_here += 1
                    if r is None:
                        break
                    xt, ft, gt = r
                    kt = key_of(ft, gt)
                    if kt < ck:
                        cur, cf, cg, ck = xt, ft, gt, kt
                        improved = True
                        break
                if improved:
                    s = min(0.5, s * 1.5)
                else:
                    s = max(1e-4, s * 0.8)
                if self.used >= self.budget:
                    break
            return cur, cf, cg, ck, s

        NP = max(10, min(40, 4 * dim))
        NP = min(NP, max(4, self.budget // 10))

        n0 = min(4 * NP, max(NP, self.budget // 4))
        pool = []
        for _ in range(n0):
            r = evaluate(rand_point())
            if r is None:
                break
            pool.append(r)
        if len(pool) < 4:
            return best["f"], best["x"]
        pool_keys = [key_of(p[1], p[2]) for p in pool]
        order0 = sorted(range(len(pool)), key=lambda j: pool_keys[j])[:NP]
        X = np.array([pool[j][0] for j in order0])
        F = [pool[j][1] for j in order0]
        G = [pool[j][2] for j in order0]
        S = [0.05 for _ in range(len(X))]
        NP = len(X)

        stall = 0
        CR = 0.7
        P_MID = 0.35
        P_LOCAL = 0.2
        P_PROBE = 0.05
        P_EXT = 0.35
        succ_hist = []
        ps_glob = 0.03
        while self.used < self.budget:
            keys = [key_of(F[j], G[j]) for j in range(NP)]

            # Pre-feasibility: antithetic pursuit on the three least-violating individuals
            if best["x"] is None and self.used < self.budget:
                order_p = sorted(range(NP), key=lambda j: keys[j])[:3]
                for b0 in order_p:
                    if self.used >= self.budget:
                        break
                    x, f, g, kk, sn = pursue(X[b0], F[b0], G[b0], keys[b0], 12, S[b0])
                    X[b0] = x; F[b0] = f; G[b0] = g; keys[b0] = kk; S[b0] = sn
                if self.used >= self.budget:
                    break

            prev_best_key = min(keys)
            for i in range(NP):
                if self.used >= self.budget:
                    break
                bi = min(range(NP), key=lambda j: keys[j])

                if best["x"] is not None and rng.rand() < P_LOCAL:
                    prev_bf = best["f"]
                    prev_bx = best["x"].copy()
                    u = rng.rand()
                    use_ext = (ext["step"] is not None and len(cont)
                               and u < P_EXT)
                    if use_ext:
                        cand = extrapolate(prev_bx)
                    elif rng.rand() < P_PROBE / max(P_LOCAL, 1e-9) and len(cont):
                        cand = coord_probe(prev_bx)
                    else:
                        cand = local_move(prev_bx)
                    r = evaluate(cand)
                    if r is None:
                        break
                    xt, ft, gt = r
                    kt = key_of(ft, gt)
                    succ = (kt[0] == 0 and ft < prev_bf)
                    if use_ext:
                        if succ:
                            ext["step"] = xt - prev_bx
                            ext["fail"] = 0
                        else:
                            ext["fail"] += 1
                            if ext["fail"] >= 3:
                                ext["step"] = None
                                ext["fail"] = 0
                    elif succ and len(cont):
                        ext["step"] = xt - prev_bx
                        ext["fail"] = 0
                    succ_hist.append(1.0 if succ else 0.0)
                    if len(succ_hist) >= 10:
                        rate = np.mean(succ_hist[-10:])
                        if rate > 0.2:
                            sig["loc"] = min(0.1, sig["loc"] * 1.3)
                        else:
                            sig["loc"] = max(1e-4, sig["loc"] * 0.85)
                    if kt <= keys[i]:
                        X[i] = xt; F[i] = ft; G[i] = gt; keys[i] = kt
                    continue

                cands = [j for j in range(NP) if j != i]
                r0, r1, r2 = rng.choice(cands, 3, replace=False)
                Fm = rng.uniform(0.4, 0.9)
                if rng.rand() < 0.5:
                    v = X[r0] + Fm * (X[r1] - X[r2])
                else:
                    v = X[i] + Fm * (X[bi] - X[i]) + Fm * (X[r1] - X[r2])

                trial = X[i].copy()
                mask = rng.rand(dim) < CR
                mask[rng.randint(dim)] = True

                if len(cont):
                    cm = mask[cont]
                    tmp = trial[cont]
                    tmp[cm] = v[cont][cm]
                    trial[cont] = tmp

                for k in ints:
                    if not mask[k]:
                        continue
                    u = rng.rand()
                    if u < 0.4:
                        trial[k] = X[bi][k]
                    elif u < 0.65:
                        trial[k] = X[r0][k]
                    elif u < 0.85 and is_ord[k]:
                        step = 1 if rng.rand() < 0.5 else -1
                        trial[k] = X[i][k] + step
                    else:
                        trial[k] = rng.randint(0, nv[k])

                r = evaluate(trial)
                if r is None:
                    break
                xt, ft, gt = r
                kt = key_of(ft, gt)
                if kt <= keys[i]:
                    X[i] = xt; F[i] = ft; G[i] = gt; keys[i] = kt

                if (kt[0] == 1 and best["x"] is not None
                        and rng.rand() < P_MID and self.used < self.budget):
                    xb = best["x"]
                    a = rng.choice([0.25, 0.5, 0.75]) if rng.rand() < 0.5 else rng.uniform(0.2, 0.8)
                    xm = xt.copy()
                    if len(cont):
                        xm[cont] = a * xt[cont] + (1 - a) * xb[cont]
                    if len(ints):
                        pick = rng.rand(len(ints)) < (1 - a)
                        xm[ints] = np.where(pick, xb[ints], xt[ints])
                    r2 = evaluate(xm)
                    if r2 is None:
                        break
                    xm2, fm2, gm2 = r2
                    km = key_of(fm2, gm2)
                    if km <= keys[i]:
                        X[i] = xm2; F[i] = fm2; G[i] = gm2; keys[i] = km

            if self.used >= self.budget:
                break

            cur_best_key = min(key_of(F[j], G[j]) for j in range(NP))
            if cur_best_key < prev_best_key:
                stall = 0
            else:
                stall += 1

            # Pre-feasibility stagnation: re-seed the worst half around the least-violators
            if best["x"] is None and stall >= 3:
                keys = [key_of(F[j], G[j]) for j in range(NP)]
                order = sorted(range(NP), key=lambda j: keys[j])
                keep = order[:max(2, NP // 2)]
                newX = [X[j].copy() for j in keep]
                newF = [F[j] for j in keep]
                newG = [G[j] for j in keep]
                newS = [S[j] for j in keep]
                for _ in range(NP - len(keep)):
                    if self.used >= self.budget:
                        break
                    base = X[keep[rng.randint(len(keep))]]
                    x0 = perturb(base, rng.choice([0.05, 0.2])) if rng.rand() < 0.5 else rand_point()
                    r = evaluate(x0)
                    if r is None:
                        break
                    newX.append(r[0]); newF.append(r[1]); newG.append(r[2]); newS.append(0.05)
                X = np.array(newX)
                F = newF
                G = newG
                S = newS
                NP = len(X)
                stall = 0
                continue

            if best["x"] is not None and stall >= 5:
                keys = [key_of(F[j], G[j]) for j in range(NP)]
                order = sorted(range(NP), key=lambda j: keys[j])
                n_elite = max(2, NP // 5)
                newX = [X[j].copy() for j in order[:n_elite]]
                newF = [F[j] for j in order[:n_elite]]
                newG = [G[j] for j in order[:n_elite]]
                ext["step"] = None
                ext["fail"] = 0
                for _ in range(NP - n_elite):
                    if self.used >= self.budget:
                        break
                    if rng.rand() < 0.6:
                        x0 = perturb(best["x"])
                    else:
                        x0 = rand_point()
                    r = evaluate(x0)
                    if r is None:
                        break
                    newX.append(r[0]); newF.append(r[1]); newG.append(r[2])
                X = np.array(newX)
                F = newF
                G = newG
                NP = len(X)
                S = [0.05] * NP
                stall = 0

        return best["f"], best["x"]
